import functools
import json
import multiprocessing
import os
import threading
from contextlib import contextmanager
from threading import Thread

from ._colorizer import Colorizer
from ._locks_machinery import create_handler_lock


def prepare_colored_format(format_, ansi_level):
    colored = Colorizer.prepare_format(format_)
    return colored, colored.colorize(ansi_level)


def prepare_stripped_format(format_):
    colored = Colorizer.prepare_format(format_)
    return colored.strip()


def memoize(function):
    return functools.lru_cache(maxsize=64)(function)


class Message(str):
    __slots__ = ("record",)


class Handler:
    def __init__(
        self,
        *,
        sink,
        name,
        levelno,
        formatter,
        is_formatter_dynamic,
        filter_,
        colorize,
        serialize,
        enqueue,
        multiprocessing_context,
        error_interceptor,
        exception_formatter,
        id_,
        levels_ansi_codes
    ):
        self._name = name
        self._sink = sink
        self._levelno = levelno
        self._formatter = formatter
        self._is_formatter_dynamic = is_formatter_dynamic
        self._filter = filter_
        self._colorize = colorize
        self._serialize = serialize
        self._enqueue = enqueue
        self._multiprocessing_context = multiprocessing_context
        self._error_interceptor = error_interceptor
        self._exception_formatter = exception_formatter
        self._id = id_
        self._levels_ansi_codes = levels_ansi_codes  # Warning, reference shared among handlers

        self._decolorized_format = None
        self._precolorized_formats = {}
        self._memoize_dynamic_format = None

        self._stopped = False
        self._lock = create_handler_lock()
        self._lock_acquired = threading.local()
        self._queue = None
        self._queue_lock = None
        self._confirmation_event = None
        self._confirmation_lock = None
        self._owner_process_pid = None
        self._thread = None

        if self._is_formatter_dynamic:
            if self._colorize:
                self._memoize_dynamic_format = memoize(prepare_colored_format)
            else:
                self._memoize_dynamic_format = memoize(prepare_stripped_format)
        else:
            if self._colorize:
                for level_name in self._levels_ansi_codes:
                    self.update_format(level_name)
            else:
                self._decolorized_format = self._formatter.strip()

        if self._enqueue:
            if self._multiprocessing_context is None:
                self._queue = multiprocessing.SimpleQueue()
                self._confirmation_event = multiprocessing.Event()
                self._confirmation_lock = multiprocessing.Lock()
            else:
                self._queue = self._multiprocessing_context.SimpleQueue()
                self._confirmation_event = self._multiprocessing_context.Event()
                self._confirmation_lock = self._multiprocessing_context.Lock()
            self._queue_lock = create_handler_lock()
            self._owner_process_pid = os.getpid()
            self._thread = Thread(
                target=self._queued_writer, daemon=True, name="loguru-writer-%d" % self._id
            )
            self._thread.start()

    def __repr__(self):
        return "(id=%d, level=%d, sink=%s)" % (self._id, self._levelno, self._name)

    @contextmanager
    def _protected_lock(self):
        """Acquire the lock, but fail fast if its already acquired by the current thread."""
        if getattr(self._lock_acquired, "acquired", False):
            raise RuntimeError(
                "Could not acquire internal lock because it was already in use (deadlock avoided). "
                "This likely happened because the logger was re-used inside a sink, a signal "
                "handler or a '__del__' method. This is not permitted because the logger and its "
                "handlers are not re-entrant."
            )
        try:
            self._lock_acquired.acquired = True
            with self._lock:
                yield
        finally:
            self._lock_acquired.acquired = False

    def emit(self, record, level_id, from_decorator, is_raw, colored_message):
        try:
            if self._levelno > record["level"].no:
                return

            if self._filter is not None:
                if not self._filter(record):
                    return

            if self._is_formatter_dynamic:
                dynamic_format = self._formatter(record)

            formatter_record = record.copy()

            if not record["exception"]:
                formatter_record["exception"] = ""
            else:
                type_, value, tb = record["exception"]
                formatter = self._exception_formatter
                lines = formatter.format_exception(type_, value, tb, from_decorator=from_decorator)
                formatter_record["exception"] = "".join(lines)

            if colored_message is not None and colored_message.stripped != record["message"]:
                colored_message = None

            if is_raw:
                if colored_message is None or not self._colorize:
                    formatted = record["message"]
                else:
                    ansi_level = self._levels_ansi_codes[level_id]
                    formatted = colored_message.colorize(ansi_level)
            elif self._is_formatter_dynamic:
                if not self._colorize:
                    precomputed_format = self._memoize_dynamic_format(dynamic_format)
                    formatted = self._format_record(precomputed_format, formatter_record)
                elif colored_message is None:
                    ansi_level = self._levels_ansi_codes[level_id]
                    _, precomputed_format = self._memoize_dynamic_format(dynamic_format, ansi_level)
                    formatted = self._format_record(precomputed_format, formatter_record)
                else:
                    ansi_level = self._levels_ansi_codes[level_id]
                    formatter, precomputed_format = self._memoize_dynamic_format(
                        dynamic_format, ansi_level
                    )
                    coloring_message = formatter.make_coloring_message(
                        record["message"], ansi_level=ansi_level, colored_message=colored_message
                    )
                    formatter_record["message"] = coloring_message
                    formatted = self._format_record(precomputed_format, formatter_record)

            else:
                if not self._colorize:
                    precomputed_format = self._decolorized_format
                    formatted = self._format_record(precomputed_format, formatter_record)
                elif colored_message is None:
                    ansi_level = self._levels_ansi_codes[level_id]
                    precomputed_format = self._precolorized_formats[level_id]
                    formatted = self._format_record(precomputed_format, formatter_record)
                else:
                    ansi_level = self._levels_ansi_codes[level_id]
                    precomputed_format = self._precolorized_formats[level_id]
                    coloring_message = self._formatter.make_coloring_message(
                        record["message"], ansi_level=ansi_level, colored_message=colored_message
                    )
                    formatter_record["message"] = coloring_message
                    formatted = self._format_record(precomputed_format, formatter_record)

            if self._serialize:
                formatted = self._serialize_record(formatted, record)

            str_record = Message(formatted)
            str_record.record = record

            with self._protected_lock():
                if self._stopped:
                    return
                if self._enqueue:
                    self._queue.put(str_record)
                else:
                    self._sink.write(str_record)
        except Exception:
            if not self._error_interceptor.should_catch():
                raise
            self._error_interceptor.print(record)

    def stop(self):
        with self._protected_lock():
            self._stopped = True
            if self._enqueue:
                if self._owner_process_pid != os.getpid():
                    return
                self._queue.put(None)
                self._thread.join()
                if hasattr(self._queue, "close"):
                    self._queue.close()

            self._sink.stop()

    def complete_queue(self):
        if not self._enqueue:
            return

        with self._confirmation_lock:
            self._queue.put(True)
            self._confirmation_event.wait()
            self._confirmation_event.clear()

    def tasks_to_complete(self):
        if self._enqueue and self._owner_process_pid != os.getpid():
            return []
        lock = self._queue_lock if self._enqueue else self._protected_lock()
        with lock:
            return self._sink.tasks_to_complete()

    def update_format(self, level_id):
        if not self._colorize or self._is_formatter_dynamic:
            return
        ansi_code = self._levels_ansi_codes[level_id]
        self._precolorized_formats[level_id] = self._formatter.colorize(ansi_code)

    @property
    def levelno(self):
        return self._levelno

    @staticmethod
    def _format_record(log_format, record):
        try:
            return log_format.format_map(record)
        except KeyError as e:
            available = ", ".join(map(repr, record.keys()))
            raise ValueError(
                "Failed to format log record: key %s not found.\n"
                "Verify that the format string %r only references valid record keys "
                "and that all required extra keys are present.\n"
                "Available records key are: %s.\n"
                "While using a dynamic formatter as a function, note that it must return "
                "the string to be formatted, not an already formatted message.\n"
                "To include custom data, use 'logger.bind(key=value)' and reference it "
                "as '{extra[key]}' in the format string." % (e, log_format, available)
            ) from e

    @staticmethod
    def _serialize_record(text, record):
        exception = record["exception"]

        if exception is not None:
            exception = {
                "type": None if exception.type is None else exception.type.__name__,
                "value": exception.value,
                "traceback": bool(exception.traceback),
            }

        serializable = {
            "text": text,
            "record": {
                "elapsed": {
                    "repr": record["elapsed"],
                    "seconds": record["elapsed"].total_seconds(),
                },
                "exception": exception,
                "extra": record["extra"],
                "file": {"name": record["file"].name, "path": record["file"].path},
                "function": record["function"],
                "level": {
                    "icon": record["level"].icon,
                    "name": record["level"].name,
                    "no": record["level"].no,
                },
                "line": record["line"],
                "message": record["message"],
                "module": record["module"],
                "name": record["name"],
                "process": {"id": record["process"].id, "name": record["process"].name},
                "template": record["template"],
                "thread": {"id": record["thread"].id, "name": record["thread"].name},
                "time": {"repr": record["time"], "timestamp": record["time"].timestamp()},
            },
        }

        return json.dumps(serializable, default=str, ensure_ascii=False) + "\n"

    def _queued_writer(self):
        message = None
        queue = self._queue

        # We need to use a lock to protect sink during fork.
        # Particularly, writing to stderr may lead to deadlock in child process.
        lock = self._queue_lock

        while True:
            try:
                message = queue.get()
            except Exception:
                with lock:
                    self._error_interceptor.print(None)
                continue

            if message is None:
                break

            if message is True:
                self._confirmation_event.set()
                continue

            with lock:
                try:
                    self._sink.write(message)
                except Exception:
                    self._error_interceptor.print(message.record)

    def __getstate__(self):
        state = self.__dict__.copy()
        state["_lock"] = None
        state["_lock_acquired"] = None
        state["_memoize_dynamic_format"] = None
        if self._enqueue:
            state["_sink"] = None
            state["_thread"] = None
            state["_queue_lock"] = None
        return state

    def __setstate__(self, state):
        self.__dict__.update(state)
        self._lock = create_handler_lock()
        self._lock_acquired = threading.local()
        if self._enqueue:
            self._queue_lock = create_handler_lock()
        if self._is_formatter_dynamic:
            if self._colorize:
                self._memoize_dynamic_format = memoize(prepare_colored_format)
            else:
                self._memoize_dynamic_format = memoize(prepare_stripped_format)

"""
Polynomial and Monomial Arithmetic

A symbolic algebra system for polynomials and monomials supporting addition,
subtraction, multiplication, division, substitution, and polynomial long
division with Fraction-based exact arithmetic.

Reference: https://en.wikipedia.org/wiki/Polynomial

Complexity:
    Time:  Varies by operation
    Space: O(number of monomials)
"""

from __future__ import annotations

from collections.abc import Iterable
from fractions import Fraction
from functools import reduce
from numbers import Rational


class Monomial:
    """A monomial represented by a coefficient and variable-to-power mapping."""

    def __init__(
        self, variables: dict[int, int], coeff: int | float | Fraction | None = None
    ) -> None:
        """Create a monomial with the given variables and coefficient.

        Args:
            variables: Dictionary mapping variable indices to their powers.
            coeff: The coefficient (defaults to 0 if empty, 1 otherwise).

        Examples:
            >>> _ = Monomial({1: 1})  # (a_1)^1
            >>> _ = Monomial({1: 3, 2: 2}, 12)  # 12(a_1)^3(a_2)^2
        """
        self.variables = dict()

        if coeff is None:
            coeff = Fraction(0, 1) if len(variables) == 0 else Fraction(1, 1)
        elif coeff == 0:
            self.coeff = Fraction(0, 1)
            return

        if len(variables) == 0:
            self.coeff = Monomial._rationalize_if_possible(coeff)
            return

        for i in variables:
            if variables[i] != 0:
                self.variables[i] = variables[i]
        self.coeff = Monomial._rationalize_if_possible(coeff)

    @staticmethod
    def _rationalize_if_possible(
        num: int | float | Fraction,
    ) -> Fraction | float:
        """Convert numbers to Fraction when possible.

        Args:
            num: A numeric value.

        Returns:
            A Fraction if the input is Rational, otherwise the original value.
        """
        if isinstance(num, Rational):
            res = Fraction(num, 1)
            return Fraction(res.numerator, res.denominator)
        else:
            return num

    def equal_upto_scalar(self, other: object) -> bool:
        """Check if other is a monomial equivalent to self up to scalar multiple.

        Args:
            other: Another Monomial to compare.

        Returns:
            True if both have the same variables with the same powers.

        Raises:
            ValueError: If other is not a Monomial.
        """
        if not isinstance(other, Monomial):
            raise ValueError("Can only compare monomials.")
        return other.variables == self.variables

    def __add__(self, other: int | float | Fraction) -> Monomial:
        """Add two monomials or a monomial with a scalar.

        Args:
            other: A Monomial, int, float, or Fraction to add.

        Returns:
            The resulting Monomial.

        Raises:
            ValueError: If monomials have different variables.
        """
        if isinstance(other, (int, float, Fraction)):
            return self.__add__(Monomial({}, Monomial._rationalize_if_possible(other)))

        if not isinstance(other, Monomial):
            raise ValueError("Can only add monomials, ints, floats, or Fractions.")

        if self.variables == other.variables:
            mono = {i: self.variables[i] for i in self.variables}
            return Monomial(
                mono, Monomial._rationalize_if_possible(self.coeff + other.coeff)
            ).clean()

        raise ValueError(
            f"Cannot add {str(other)} to {self.__str__()} "
            "because they don't have same variables."
        )

    def __eq__(self, other: object) -> bool:
        """Check equality of two monomials.

        Args:
            other: Another Monomial to compare.

        Returns:
            True if both monomials are equal.
        """
        if not isinstance(other, Monomial):
            return NotImplemented
        return self.equal_upto_scalar(other) and self.coeff == other.coeff

    def __mul__(self, other: int | float | Fraction) -> Monomial:
        """Multiply two monomials or a monomial with a scalar.

        Args:
            other: A Monomial, int, float, or Fraction to multiply.

        Returns:
            The resulting Monomial.

        Raises:
            ValueError: If other is not a valid type.
        """
        if isinstance(other, (float, int, Fraction)):
            mono = {i: self.variables[i] for i in self.variables}
            return Monomial(
                mono, Monomial._rationalize_if_possible(self.coeff * other)
            ).clean()

        if not isinstance(other, Monomial):
            raise ValueError("Can only multiply monomials, ints, floats, or Fractions.")
        else:
            mono = {i: self.variables[i] for i in self.variables}
            for i in other.variables:
                if i in mono:
                    mono[i] += other.variables[i]
                else:
                    mono[i] = other.variables[i]

            temp = dict()
            for k in mono:
                if mono[k] != 0:
                    temp[k] = mono[k]

            return Monomial(
                temp, Monomial._rationalize_if_possible(self.coeff * other.coeff)
            ).clean()

    def inverse(self) -> Monomial:
        """Compute the multiplicative inverse of this monomial.

        Returns:
            The inverse Monomial.

        Raises:
            ValueError: If the coefficient is zero.
        """
        mono = {i: self.variables[i] for i in self.variables if self.variables[i] != 0}
        for i in mono:
            mono[i] *= -1
        if self.coeff == 0:
            raise ValueError("Coefficient must not be 0.")
        return Monomial(mono, Monomial._rationalize_if_possible(1 / self.coeff)).clean()

    def __truediv__(self, other: int | float | Fraction) -> Monomial:
        """Divide this monomial by another monomial or scalar.

        Args:
            other: A Monomial, int, float, or Fraction divisor.

        Returns:
            The resulting Monomial.

        Raises:
            ValueError: If dividing by zero.
        """
        if isinstance(other, (int, float, Fraction)):
            mono = {i: self.variables[i] for i in self.variables}
            if other == 0:
                raise ValueError("Cannot divide by 0.")
            return Monomial(
                mono, Monomial._rationalize_if_possible(self.coeff / other)
            ).clean()

        o = other.inverse()
        return self.__mul__(o)

    def __floordiv__(self, other: int | float | Fraction) -> Monomial:
        """Floor division (same as true division for monomials).

        Args:
            other: A Monomial, int, float, or Fraction divisor.

        Returns:
            The resulting Monomial.
        """
        return self.__truediv__(other)

    def clone(self) -> Monomial:
        """Create a deep copy of this monomial.

        Returns:
            A new Monomial with the same variables and coefficient.
        """
        temp_variables = {i: self.variables[i] for i in self.variables}
        return Monomial(
            temp_variables, Monomial._rationalize_if_possible(self.coeff)
        ).clean()

    def clean(self) -> Monomial:
        """Remove variables with zero power.

        Returns:
            A cleaned Monomial.
        """
        temp_variables = {
            i: self.variables[i] for i in self.variables if self.variables[i] != 0
        }
        return Monomial(temp_variables, Monomial._rationalize_if_possible(self.coeff))

    def __sub__(self, other: int | float | Fraction) -> Monomial:
        """Subtract a value from this monomial.

        Args:
            other: A Monomial, int, float, or Fraction to subtract.

        Returns:
            The resulting Monomial.

        Raises:
            ValueError: If monomials have different variables.
        """
        if isinstance(other, (int, float, Fraction)):
            mono = {
                i: self.variables[i] for i in self.variables if self.variables[i] != 0
            }
            if len(mono) != 0:
                raise ValueError("Can only subtract like monomials.")
            other_term = Monomial(mono, Monomial._rationalize_if_possible(other))
            return self.__sub__(other_term)
        if not isinstance(other, Monomial):
            raise ValueError("Can only subtract monomials")
        return self.__add__(other.__mul__(Fraction(-1, 1)))

    def __hash__(self) -> int:
        """Hash based on the underlying variables.

        Returns:
            An integer hash value.
        """
        arr = []
        for i in sorted(self.variables):
            if self.variables[i] > 0:
                for _ in range(self.variables[i]):
                    arr.append(i)
        return hash(tuple(arr))

    def all_variables(self) -> set:
        """Get the set of all variable indices in this monomial.

        Returns:
            A set of variable indices.
        """
        return set(sorted(self.variables.keys()))

    def substitute(
        self,
        substitutions: int | float | Fraction | dict[int, int | float | Fraction],
    ) -> Fraction:
        """Evaluate the monomial by substituting values for variables.

        Args:
            substitutions: A single value applied to all variables, or a
                dict mapping variable indices to values.

        Returns:
            The evaluated result.

        Raises:
            ValueError: If some variables are not given values.
        """
        if isinstance(substitutions, (int, float, Fraction)):
            substitutions = {
                v: Monomial._rationalize_if_possible(substitutions)
                for v in self.all_variables()
            }
        else:
            if not self.all_variables().issubset(set(substitutions.keys())):
                raise ValueError("Some variables didn't receive their values.")
        if self.coeff == 0:
            return Fraction(0, 1)
        ans = Monomial._rationalize_if_possible(self.coeff)
        for k in self.variables:
            ans *= Monomial._rationalize_if_possible(
                substitutions[k] ** self.variables[k]
            )
        return Monomial._rationalize_if_possible(ans)

    def __str__(self) -> str:
        """Get a string representation of the monomial.

        Returns:
            A human-readable string.
        """
        if len(self.variables) == 0:
            return str(self.coeff)

        result = str(self.coeff)
        result += "("
        for i in self.variables:
            temp = f"a_{str(i)}"
            if self.variables[i] > 1:
                temp = "(" + temp + f")**{self.variables[i]}"
            elif self.variables[i] < 0:
                temp = "(" + temp + f")**(-{-self.variables[i]})"
            elif self.variables[i] == 0:
                continue
            else:
                temp = "(" + temp + ")"
            result += temp
        return result + ")"


class Polynomial:
    """A polynomial represented as a set of Monomial terms."""

    def __init__(
        self, monomials: Iterable[int | float | Fraction | Monomial]
    ) -> None:
        """Create a polynomial from an iterable of monomials or scalars.

        Args:
            monomials: An iterable of Monomial, int, float, or Fraction values.

        Raises:
            ValueError: If an element is not a valid type.
        """
        self.monomials: set = set()
        for m in monomials:
            if any(map(lambda x: isinstance(m, x), [int, float, Fraction])):
                self.monomials |= {Monomial({}, m)}
            elif isinstance(m, Monomial):
                self.monomials |= {m}
            else:
                raise ValueError(
                    "Iterable should have monomials, int, float, or Fraction."
                )
        self.monomials -= {Monomial({}, 0)}

    @staticmethod
    def _rationalize_if_possible(
        num: int | float | Fraction,
    ) -> Fraction | float:
        """Convert numbers to Fraction when possible.

        Args:
            num: A numeric value.

        Returns:
            A Fraction if the input is Rational, otherwise the original value.
        """
        if isinstance(num, Rational):
            res = Fraction(num, 1)
            return Fraction(res.numerator, res.denominator)
        else:
            return num

    def __add__(self, other: int | float | Fraction | Monomial) -> Polynomial:
        """Add a polynomial, monomial, or scalar to this polynomial.

        Args:
            other: Value to add.

        Returns:
            The resulting Polynomial.

        Raises:
            ValueError: If other is not a valid type.
        """
        if isinstance(other, (int, float, Fraction)):
            return self.__add__(
                Monomial({}, Polynomial._rationalize_if_possible(other))
            )
        elif isinstance(other, Monomial):
            monos = {m.clone() for m in self.monomials}

            for _own_monos in monos:
                if _own_monos.equal_upto_scalar(other):
                    scalar = _own_monos.coeff
                    monos -= {_own_monos}
                    temp_variables = {i: other.variables[i] for i in other.variables}
                    monos |= {
                        Monomial(
                            temp_variables,
                            Polynomial._rationalize_if_possible(scalar + other.coeff),
                        )
                    }
                    return Polynomial([z for z in monos])

            monos |= {other.clone()}
            return Polynomial([z for z in monos])
        elif isinstance(other, Polynomial):
            temp = list(z for z in {m.clone() for m in self.all_monomials()})

            p = Polynomial(temp)
            for o in other.all_monomials():
                p = p.__add__(o.clone())
            return p
        else:
            raise ValueError(
                "Can only add int, float, Fraction, Monomials, "
                "or Polynomials to Polynomials."
            )

    def __sub__(self, other: int | float | Fraction | Monomial) -> Polynomial:
        """Subtract a polynomial, monomial, or scalar from this polynomial.

        Args:
            other: Value to subtract.

        Returns:
            The resulting Polynomial.

        Raises:
            ValueError: If other is not a valid type.
        """
        if isinstance(other, (int, float, Fraction)):
            return self.__sub__(
                Monomial({}, Polynomial._rationalize_if_possible(other))
            )
        elif isinstance(other, Monomial):
            monos = {m.clone() for m in self.all_monomials()}
            for _own_monos in monos:
                if _own_monos.equal_upto_scalar(other):
                    scalar = _own_monos.coeff
                    monos -= {_own_monos}
                    temp_variables = {i: other.variables[i] for i in other.variables}
                    monos |= {
                        Monomial(
                            temp_variables,
                            Polynomial._rationalize_if_possible(scalar - other.coeff),
                        )
                    }
                    return Polynomial([z for z in monos])

            to_insert = other.clone()
            to_insert.coeff *= -1

            monos |= {to_insert}
            return Polynomial([z for z in monos])

        elif isinstance(other, Polynomial):
            p = Polynomial(list(z for z in {m.clone() for m in self.all_monomials()}))
            for o in other.all_monomials():
                p = p.__sub__(o.clone())
            return p

        else:
            raise ValueError(
                "Can only subtract int, float, Fraction, "
                "Monomials, or Polynomials from Polynomials."
            )

    def __mul__(self, other: int | float | Fraction | Monomial) -> Polynomial:
        """Multiply this polynomial by another polynomial, monomial, or scalar.

        Args:
            other: Value to multiply by.

        Returns:
            The resulting Polynomial.

        Raises:
            ValueError: If other is not a valid type.
        """
        if isinstance(other, (int, float, Fraction, Monomial)):
            result = Polynomial([])
            monos = {m.clone() for m in self.all_monomials()}
            for m in monos:
                result = result.__add__(m.clone() * other)
